package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.time.LocalDate;
@Entity @Table(name="onboarding_tasks") public class OnboardingTask { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; private String taskName; private String owner; private String status="PENDING"; private LocalDate dueDate; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getTaskName(){return taskName;} public void setTaskName(String v){taskName=v;} public String getOwner(){return owner;} public void setOwner(String v){owner=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} }
